function respond(bool $ok,string $message,array $data=[],int $code=200):void{http_response_code($code);echo json_encode(['status'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE);exit;}
function prep(mysqli $db,string $sql,string $label):mysqli_stmt{$s=$db->prepare($sql);if(!$s)throw new RuntimeException($label.': '.$db->error);return $s;}
function bindMany(mysqli_stmt $s,string $types,array &$values):void{$args=[$types];foreach($values as &$v){$args[]=&$v;}call_user_func_array([$s,'bind_param'],$args);}
function tableExists(mysqli $db,string $name):bool{$safe=$db->real_escape_string($name);$r=$db->query("SHOW TABLES LIKE '$safe'");return $r instanceof mysqli_result&&$r->num_rows>0;}
function currentUser():string{global $loginname;return trim((string)($loginname??$_SESSION['loginname']??$_SESSION['username']??'System'));}
function financialYear(string $date,int $start):string{$y=(int)substr($date,0,4);if((int)substr($date,5,2)<$start)$y--;return $y.'-'.substr((string)($y+1),-2);}
function invoiceNumber(int $id,string $fy,array $cfg):string{return strtr((string)$cfg['invoice_number_format'],['{PREFIX}'=>(string)$cfg['invoice_prefix'],'{FY_SHORT}'=>str_replace('-','',$fy),'{SEQ5}'=>str_pad((string)$id,5,'0',STR_PAD_LEFT)]);}
function money($v):float{return round((float)$v,2);}

function availableAdvance(mysqli $k,mysqli $m,int $project,string $client,string $psono):float{
 $s=prep($k,"SELECT COALESCE(SUM(advanceamount),0) total FROM advance_payment_transactions WHERE projectid=? AND clientid=? AND paymentref_no=? AND verification='verified' AND COALESCE(tedit,'') NOT IN ('1','Deleted','deleted')",'Advance lookup failed');
 $s->bind_param('iss',$project,$client,$psono);$s->execute();$total=(float)($s->get_result()->fetch_assoc()['total']??0);$s->close();
 if(!tableExists($m,'tbl_client_ledger_entry')||!tableExists($m,'tbl_client_ledger_allocation'))return max(0,$total);
 $s=prep($m,"SELECT COALESCE(SUM(a.allocated_amount),0) used FROM tbl_client_ledger_allocation a JOIN tbl_client_ledger_entry e ON e.id=a.credit_entry_id WHERE a.projectid=? AND a.client_id=? AND e.source_type='ADVANCE_PAYMENT' AND e.psono=?",'Advance allocation lookup failed');
 $s->bind_param('iss',$project,$client,$psono);$s->execute();$used=(float)($s->get_result()->fetch_assoc()['used']??0);$s->close();return max(0,$total-$used);
}

function pending(mysqli $k,mysqli $m,int $project):array{
 $sql="SELECT s.clientid,MAX(pd.clientname) clientname,s.trip_id,MAX(t.dispatch_at) trip_date,MAX(t.vehicle_no) vehicle_no,MAX(t.driver_name) driver_name,pd.psono,pd.sono,pd.sales_order_item_id,pd.productid,MAX(pd.productname) productname,GROUP_CONCAT(s.id ORDER BY s.id) scan_ids,SUM(s.qty-COALESCE(li.invoiced_qty,0)) dispatched_qty,MAX(soi.rate) rate,MAX(COALESCE(soi.discount_percent,0)) discount_percent FROM krf_transport_trip_scan s JOIN krf_transport_trip t ON t.projectid=s.projectid AND t.trip_id=s.trip_id AND t.transport_type='Client' JOIN krf_client_dispatch_plan_detail pd ON pd.id=s.client_dispatch_plan_detail_id AND pd.projectid=s.projectid JOIN krf_sales_order_items soi ON soi.id=pd.sales_order_item_id AND soi.projectid=pd.projectid LEFT JOIN (SELECT projectid,scan_id,SUM(invoiced_qty) invoiced_qty FROM krf_transport_sale_invoice_link GROUP BY projectid,scan_id) li ON li.projectid=s.projectid AND li.scan_id=s.id WHERE s.projectid=? AND s.transport_type='Client' AND s.status='Loaded' AND t.status IN ('In-Transit','In Transit','Delivered','Received','Completed') AND s.qty>COALESCE(li.invoiced_qty,0) GROUP BY s.clientid,s.trip_id,pd.psono,pd.sono,pd.sales_order_item_id,pd.productid ORDER BY MAX(pd.clientname),pd.psono,MAX(pd.productname)";
 $s=prep($k,$sql,'Pending invoice lookup failed');$s->bind_param('i',$project);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$cache=[];
 foreach($rows as &$r){$key=$r['clientid'].'|'.$r['psono'];if(!isset($cache[$key]))$cache[$key]=availableAdvance($k,$m,$project,(string)$r['clientid'],(string)$r['psono']);$r['available_advance']=$cache[$key];$gross=(float)$r['dispatched_qty']*(float)$r['rate'];$r['line_amount']=money($gross-$gross*(float)$r['discount_percent']/100);$r['line_key']=$r['trip_id'].'|'.$r['sales_order_item_id'].'|'.$r['psono'].'|'.$r['productid'];}unset($r);return $rows;
}

function generated(mysqli $k,mysqli $m,int $project):array{
 $s=prep($k,"SELECT invoice_id,MAX(invoice_no) invoice_no,MAX(invoice_date) invoice_date,MAX(invoice_path) invoice_path,clientid,GROUP_CONCAT(DISTINCT trip_id ORDER BY trip_id SEPARATOR ',') trip_ids,SUM(invoiced_qty) total_qty FROM krf_transport_sale_invoice_link WHERE projectid=? GROUP BY invoice_id,clientid ORDER BY MAX(invoice_date) DESC,invoice_id DESC",'Generated invoice lookup failed');
 $s->bind_param('i',$project);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
 foreach($rows as &$r){$iid=(int)$r['invoice_id'];$h=prep($m,"SELECT client_name,invoice_amount FROM tbl_invoices WHERE invoice_id=? AND invoice_type='Sale Invoice' LIMIT 1",'Invoice header lookup failed');$h->bind_param('i',$iid);$h->execute();$a=$h->get_result()->fetch_assoc()?:[];$h->close();$r['clientname']=$a['client_name']??$r['clientid'];$r['invoice_amount']=(float)($a['invoice_amount']??0);$r['vehicle_no']='';$r['driver_name']='';$trips=array_values(array_filter(explode(',',(string)$r['trip_ids'])));if($trips){$marks=implode(',',array_fill(0,count($trips),'?'));$q=prep($k,"SELECT GROUP_CONCAT(DISTINCT NULLIF(TRIM(vehicle_no),'') SEPARATOR ', ') vehicle_no,GROUP_CONCAT(DISTINCT NULLIF(TRIM(driver_name),'') SEPARATOR ', ') driver_name FROM krf_transport_trip WHERE projectid=? AND trip_id IN ($marks)",'Vehicle lookup failed');$args=array_merge([$project],$trips);bindMany($q,'i'.str_repeat('s',count($trips)),$args);$q->execute();$v=$q->get_result()->fetch_assoc()?:[];$q->close();$r['vehicle_no']=$v['vehicle_no']??'';$r['driver_name']=$v['driver_name']??'';}}unset($r);return $rows;
}

function ledgerAccount(mysqli $m,int $co,int $sub,int $project,string $client,string $name,string $by):array{$code='CL-'.$client;$s=prep($m,"INSERT INTO tbl_client_ledger_account(companyid,subcompanyid,projectid,client_id,client_name,account_code,created_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE client_name=VALUES(client_name),id=LAST_INSERT_ID(id)",'Ledger account failed');$s->bind_param('iiissss',$co,$sub,$project,$client,$name,$code,$by);$s->execute();$id=(int)$m->insert_id;$s->close();return[$id,$code];}

